import{_ as d,o as r,c as a,ag as e}from"./chunks/framework.BcZEdlUI.js";const u=JSON.parse('{"title":"功能矩阵","description":"SceneFab 产品能力、开发状态与适用场景。","frontmatter":{"title":"功能矩阵","description":"SceneFab 产品能力、开发状态与适用场景。"},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1781612722000}'),h={name:"features.md"};function o(l,t,i,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="功能矩阵" tabindex="-1">功能矩阵 <a class="header-anchor" href="#功能矩阵" aria-label="Permalink to &quot;功能矩阵&quot;">​</a></h1><p>SceneFab 是面向影视/短剧第一人称解说的生产工具，将素材理解、脚本生成、配音字幕和平台导出串成标准化流程。以下按功能模块列出当前能力与开发状态。</p><h2 id="功能状态说明" tabindex="-1">功能状态说明 <a class="header-anchor" href="#功能状态说明" aria-label="Permalink to &quot;功能状态说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标记</th><th>含义</th></tr></thead><tbody><tr><td>已发布</td><td>功能完整可用，经过测试验证</td></tr><tr><td>开发中</td><td>核心逻辑已实现，正在完善边界场景</td></tr><tr><td>计划中</td><td>已列入开发计划，尚未开始实现</td></tr></tbody></table><h2 id="视频理解" tabindex="-1">视频理解 <a class="header-anchor" href="#视频理解" aria-label="Permalink to &quot;视频理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能模块</th><th>能力</th><th>状态</th></tr></thead><tbody><tr><td>场景分析</td><td>自动识别场景切换、提取关键帧和画面摘要</td><td>已发布</td></tr><tr><td>人物识别</td><td>识别画面中的人物、推断角色关系</td><td>已发布</td></tr><tr><td>情绪峰值</td><td>检测冲突、反转、高潮等情绪节点</td><td>已发布</td></tr><tr><td>桥段检测</td><td>识别短剧常见桥段（打脸、逆袭、误会等）</td><td>已发布</td></tr><tr><td>剧情图谱</td><td>构建 StoryGraph，追踪人物和剧情线</td><td>已发布</td></tr><tr><td>多场景长视频</td><td>支持电影/剧集级别的长视频分段理解</td><td>已发布</td></tr><tr><td>音频线索提取</td><td>从原片音频中提取对白和声音事件</td><td>开发中</td></tr></tbody></table><h2 id="解说生成" tabindex="-1">解说生成 <a class="header-anchor" href="#解说生成" aria-label="Permalink to &quot;解说生成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能模块</th><th>能力</th><th>状态</th></tr></thead><tbody><tr><td>第一人称脚本</td><td>生成 Hook、主体、反击、收束和钩子结构的解说稿</td><td>已发布</td></tr><tr><td>Hook 改写</td><td>自动生成多个 Hook 变体供选择</td><td>已发布</td></tr><tr><td>桥段模板</td><td>基于桥段标签自动匹配叙事模板</td><td>已发布</td></tr><tr><td>前情承接</td><td>连载模式下自动引用前集摘要，避免重复解释</td><td>已发布</td></tr><tr><td>下集钩子</td><td>自动生成结尾悬念，引导观看下一集</td><td>已发布</td></tr><tr><td>多模型复核</td><td>支持跨模型交叉审核脚本质量</td><td>已发布</td></tr><tr><td>字数约束</td><td>按平台和时长自动控制脚本字数</td><td>已发布</td></tr><tr><td>风格迁移</td><td>将脚本在不同叙事风格间转换</td><td>计划中</td></tr></tbody></table><h2 id="配音合成" tabindex="-1">配音合成 <a class="header-anchor" href="#配音合成" aria-label="Permalink to &quot;配音合成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能模块</th><th>能力</th><th>状态</th></tr></thead><tbody><tr><td>Edge-TTS 配音</td><td>使用 Edge-TTS 生成解说音频，支持多音色</td><td>已发布</td></tr><tr><td>F5-TTS 音色克隆</td><td>基于参考音频克隆音色，保持人设一致</td><td>已发布</td></tr><tr><td>语速调节</td><td>按百分比调整配音语速</td><td>已发布</td></tr><tr><td>音调调节</td><td>按 Hz 调整配音音调</td><td>已发布</td></tr><tr><td>时间戳对齐</td><td>配音音频自动生成字幕时间戳</td><td>已发布</td></tr><tr><td>多语言配音</td><td>支持英语、日语等多语言解说</td><td>计划中</td></tr></tbody></table><h2 id="字幕处理" tabindex="-1">字幕处理 <a class="header-anchor" href="#字幕处理" aria-label="Permalink to &quot;字幕处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能模块</th><th>能力</th><th>状态</th></tr></thead><tbody><tr><td>SRT 字幕生成</td><td>基于配音时间戳自动生成 SRT 字幕文件</td><td>已发布</td></tr><tr><td>安全区控制</td><td>字幕自动避开平台互动栏和标题区</td><td>已发布</td></tr><tr><td>单双行控制</td><td>单条字幕不超过两行，自动换行</td><td>已发布</td></tr><tr><td>字幕样式</td><td>支持自定义字体、大小、颜色和描边</td><td>开发中</td></tr><tr><td>双语字幕</td><td>同时生成中英双语字幕</td><td>计划中</td></tr></tbody></table><h2 id="视频导出" tabindex="-1">视频导出 <a class="header-anchor" href="#视频导出" aria-label="Permalink to &quot;视频导出&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能模块</th><th>能力</th><th>状态</th></tr></thead><tbody><tr><td>MP4 导出</td><td>合成配音、字幕和画面为 MP4 成片</td><td>已发布</td></tr><tr><td>剪映草稿导出</td><td>导出剪映可编辑草稿，保留时间轴供二次处理</td><td>已发布</td></tr><tr><td>平台预设</td><td>预置抖音、快手、B站等平台画布和码率参数</td><td>已发布</td></tr><tr><td>竖屏/横屏</td><td>支持 9:16 竖屏和 16:9 横屏输出</td><td>已发布</td></tr><tr><td>编码选择</td><td>支持 H.264 / H.265 编码</td><td>已发布</td></tr><tr><td>质量档位</td><td>低/中/高三档输出质量</td><td>已发布</td></tr><tr><td>批量导出</td><td>一次导出多集成片</td><td>开发中</td></tr></tbody></table><h2 id="批量处理" tabindex="-1">批量处理 <a class="header-anchor" href="#批量处理" aria-label="Permalink to &quot;批量处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能模块</th><th>能力</th><th>状态</th></tr></thead><tbody><tr><td>短剧整季批量</td><td>统一标签和关系设定，按集批量生成</td><td>已发布</td></tr><tr><td>素材清单管理</td><td>批量素材的来源追踪和集数索引</td><td>已发布</td></tr><tr><td>进度追踪</td><td>批量任务的实时进度和状态反馈</td><td>已发布</td></tr><tr><td>断点续传</td><td>批量任务中断后可从断点继续</td><td>开发中</td></tr><tr><td>并行处理</td><td>多集同时处理，提升批量效率</td><td>计划中</td></tr></tbody></table><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐用法</th></tr></thead><tbody><tr><td>短剧单集解说</td><td>录入题材、爽点、人物关系和集数上下文，优先生成 30-90 秒竖屏稿</td></tr><tr><td>短剧整季批量</td><td>先统一标签和关系设定，再按集生成脚本、配音和导出记录</td></tr><tr><td>电影/剧集片段解说</td><td>先做场景拆分和情绪峰值筛选，再生成第一人称视角脚本</td></tr><tr><td>剪映继续精剪</td><td>导出剪映草稿，保留字幕、配音和时间轴供人工二次处理</td></tr></tbody></table><h2 id="不适用场景" tabindex="-1">不适用场景 <a class="header-anchor" href="#不适用场景" aria-label="Permalink to &quot;不适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td>逐帧精修调色</td><td>SceneFab 只负责生产链路，不替代专业调色软件</td></tr><tr><td>复杂多轨包装</td><td>多机位、复杂特效和商业包装建议进入专业剪辑工具继续处理</td></tr><tr><td>无版权素材搬运</td><td>项目要求素材来源可追溯，最终内容合规由使用者负责</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/scene-fab/architecture.html">架构概览</a> — 系统分层与模块职责</li><li><a href="/scene-fab/ai-models.html">AI 模型参考</a> — 模型选择与推荐配置</li><li><a href="/scene-fab/config.html">配置参考</a> — 两文件配置结构</li></ul>',22)])])}const f=d(h,[["render",o]]);export{u as __pageData,f as default};
